class EditorialNumberMeanings40to69Seeder extends Seeder {
 public function run(): void {
  $entries = [
            ['40', 'Порядок, которому можно доверять', 'Четвёрка в нумерологической традиции связана с фундаментом, а ноль усиливает образ открытого пространства. Число 40 предлагает задуматься, не превратился ли твой порядок в способ защищаться от неопределённости. Надёжная опора помогает жить, а не запрещает неожиданности.', 'Спокойная дисциплина, оставляющая место живому.', 'Страх нарушить привычный распорядок даже ради важного.', 'Какая часть моего порядка действительно служит мне?', 'Откажись сегодня от одного несущественного правила и заметь реакцию.'],
            ['41', 'Строить своё, а не чужое', 'В числе 41 символ устойчивости предшествует личной инициативе. Можно годами следовать правилам семьи, профессии или окружения, даже не замечая, какие из них ты действительно выбираешь. Взрослая самостоятельность начинается с честного пересмотра оснований.', 'Способность сохранять полезное наследие и создавать собственный путь.', 'Бунт против любых правил только ради доказательства независимости.', 'Какое правило моей жизни я никогда не выбирал сознательно?', 'Запиши одну унаследованную установку и реши, нужна ли она тебе сегодня.'],
            ['42', 'Надёжность без жертвенности', 'Четвёрка говорит о долге и структуре, двойка — о близости. Сорок два напоминает: отношения не становятся крепче от того, что один человек молча несёт всё. Доверие появляется там, где ответственность можно обсуждать и делить.', 'Умение договариваться о справедливом распределении забот.', 'Ожидание благодарности за обязанности, о которых никто не просил.', 'Где я взял на себя больше, чем готов нести?', 'Назови одну задачу, которую можно обсудить или разделить с близким.'],
            ['43', 'Не прятать живое за правильным', 'В числе 43 порядок встречается с выражением. Мы можем идеально подготовить речь, проект или разговор — и всё же не сказать главного. Чрезмерная аккуратность иногда защищает не качество, а страх показаться несовершенным.', 'Точность, в которой остаётся место искренности.', 'Постоянная правка слов, чтобы избежать оценки.', 'Какую мысль я так тщательно оформляю, что уже боюсь произнести?', 'Скажи важное простыми словами, без вступления и украшений.'],
            ['45', 'Когда опора перестаёт помогать', 'Четвёрка символизирует устойчивость, пятёрка — движение. Сорок пять напоминает о моменте, когда привычная система когда-то спасала, а теперь мешает расти. Изменение не обязательно разрушает фундамент: иногда оно показывает, какие опоры действительно прочны.', 'Гибкость без потери своих ценностей.', 'Упрямое сохранение формы ради ощущения контроля.', 'Что я продолжаю делать только потому, что всегда так делал?', 'Измени один небольшой элемент привычного маршрута или распорядка.'],
            ['46', 'Дом, в котором можно быть собой', 'Четвёрка ассоциируется с границами и домом, шестёрка — с заботой. Число 46 предлагает исследовать, не путаешь ли ты уют с обязанностью соответствовать ожиданиям. Настоящая безопасность позволяет человеку не играть роль идеального близкого.', 'Тёплые договорённости, учитывающие потребности каждого.', 'Контроль под видом заботы о семейном порядке.', 'Где дома я чувствую необходимость быть удобным?', 'Обозначь одну бытовую потребность без обвинений и оправданий.'],
            ['47', 'Тишина внутри расписания', 'Четвёрка любит организовывать, семёрка — исследовать невидимое за привычным. Сорок семь напоминает: можно отлично управлять временем и совсем не оставлять его для внутреннего вопроса. Не всякая пауза бесполезна.', 'Способность соединять практичность с созерцанием.', 'Превращение самопознания в ещё один пункт списка достижений.', 'Когда я в последний раз ничего не улучшал, а просто наблюдал?', 'Оставь пять минут без цели, таймера продуктивности и телефона.'],
            ['48', 'Результат, который не поглощает жизнь', 'Четвёрка создаёт систему, восьмёрка стремится к воплощению. В сорока восьми можно увидеть сильную рабочую энергию — и риск незаметно стать обслуживающим персоналом собственных целей. Достижения должны иметь отношение к жизни, ради которой ты трудился.', 'Последовательное созидание с ясными приоритетами.', 'Работа ради следующей отметки, не приносящей удовлетворения.', 'Какая моя цель всё ещё связана с тем, что мне дорого?', 'Рядом с одной целью запиши, ради какого переживания она тебе нужна.'],
            ['49', 'Завершить, даже если не идеально', 'Четвёрка требует порядка, девятка символизирует завершение. Сорок девять напоминает, что незаконченные дела иногда держат нас не потому, что важны, а потому, что мы не допускаем несовершенного финала. Закрыть задачу — не значит обесценить усилия.', 'Умение завершать достаточно хорошо и освобождать внимание.', 'Бесконечная доработка как способ не сталкиваться с оценкой.', 'Какое дело давно можно признать законченным?', 'Выбери один небольшой незавершённый вопрос и поставь в нём точку.'],
            ['50', 'Свобода не обязана шуметь', 'Пятёрка связана с переменами, ноль — с пространством. Пятьдесят приглашает задуматься: иногда желание немедленно всё поменять возникает не от ясности, а от усталости. Свобода может проявиться не в резком повороте, а в праве на паузу.', 'Умение выбирать перемены, а не подчиняться беспокойству.', 'Постоянный поиск нового ради ухода от себя.', 'Чего я хочу на самом деле: нового пути или отдыха?', 'Отложи одно необязательное решение на сутки и наблюдай, что меняется.'],
            ['51', 'Собственный выбор после перемен', 'В числе 51 движение предшествует личному решению. После переезда, расставания или смены работы легко продолжать жить в режиме реакции на события. Но когда внешняя буря стихает, появляется другой вопрос: что теперь выбираешь ты?', 'Возвращение инициативы после нестабильного периода.', 'Привычка объяснять все решения обстоятельствами.', 'Где я всё ещё живу так, будто не могу выбирать?', 'Найди одно маленькое решение, которое сегодня полностью в твоих руках.'],
            ['52', 'Свобода в близости', 'Пятёрка ищет движение, двойка — связь. Число 52 показывает напряжение, знакомое многим: желание быть рядом и потребность в собственном пространстве. Близость не становится слабее от честно названных границ.', 'Отношения, в которых есть место индивидуальному ритму.', 'Исчезновение без объяснений под видом независимости.', 'Какую потребность в пространстве я боюсь озвучить?', 'Договорись с близким о небольшом времени для себя, не превращая его в конфликт.'],
            ['53', 'Меняться без новой маски', 'Пятёрка символизирует перемены, тройка — самовыражение. После внутреннего поворота часто хочется немедленно объявить миру о новом себе. Но настоящее изменение не обязано быть эффектным: ему нужно время проявиться в поступках.', 'Искреннее выражение опыта без необходимости впечатлять.', 'Создание яркого образа трансформации вместо проживания изменений.', 'Что во мне меняется тихо, без свидетелей?', 'Запиши один поступок, который отражает перемену лучше любых слов.'],
            ['54', 'У перемен должен быть берег', 'В числе 54 свобода встречает структуру. Когда жизнь становится подвижной, простые ритуалы — сон, еда, прогулка, разговор — помогают не потерять ощущение земли под ногами. Стабильность не противоположна свободе; иногда она делает её возможной.', 'Гибкость, опирающаяся на заботу о базовых потребностях.', 'Попытка контролировать каждую деталь во время неопределённости.', 'Какая простая привычка поддержит меня в период перемен?', 'Выбери одну посильную опору на ближайшие три дня.'],
            ['56', 'Забота в период перемен', 'Пятёрка приносит новое, шестёрка напоминает о близких. Число 56 предлагает посмотреть, как изменения одного человека отражаются на других. Не нужно отказываться от своего пути, но важно замечать тех, кто проходит часть дороги рядом.', 'Умение обсуждать перемены с уважением к чужим чувствам.', 'Оправдание невнимательности словами «мне нужно развиваться».', 'Кого затронет моё решение и о чём стоит поговорить заранее?', 'Назови человеку одно изменение и спроси, что для него в нём трудно.'],
            ['57', 'Поиск, который не становится бегством', 'Пятёрка символизирует движение, семёрка — внутренний поиск. Пятьдесят семь напоминает о соблазне менять учения, практики и взгляды всякий раз, когда становится неуютно. Глубина иногда начинается не с нового ответа, а с готовности остаться с вопросом.', 'Любознательность, подкреплённая личным опытом.', 'Коллекционирование духовных идей вместо наблюдения за жизнью.', 'Какую мысль я изучаю, но никак не проверяю на собственном опыте?', 'Выбери одну простую практику внимания и выполни её без поиска новой техники.'],
            ['58', 'Не покупать чувство свободы', 'Пятёрка связана со свободой, восьмёрка — с ресурсами и достижениями. Число 58 помогает заметить, когда новая покупка, статус или проект обещают внутреннее облегчение. Вещи могут быть полезны, но не обязаны отвечать за наше чувство полноценности.', 'Осознанное использование ресурсов ради реальных потребностей.', 'Попытка заглушить тревогу приобретениями и достижениями.', 'Что я надеюсь почувствовать после следующей покупки или победы?', 'Прежде чем тратить деньги, назови потребность, которую хочешь удовлетворить.'],
            ['59', 'Отпустить прежнюю версию свободы', 'Пятёрка говорит о переменах, девятка — о завершении. Пятьдесят девять напоминает: иногда мы продолжаем бороться за свободу от ограничений, которых уже нет. Старый протест может стать новой клеткой, если мы не замечаем изменившихся обстоятельств.', 'Способность обновлять представление о собственном пути.', 'Автоматическое сопротивление всему, что напоминает прошлые запреты.', 'Против чего я продолжаю бороться по привычке?', 'Опиши одну ситуацию, где теперь можешь выбирать спокойнее, чем раньше.'],
            ['60', 'Забота без немедленного ответа', 'Шестёрка ассоциируется с заботой, ноль — с открытым пространством. Шестьдесят напоминает, что не каждую чужую боль можно исправить. Иногда присутствие важнее совета, а уважение к чужому переживанию — важнее нашего желания быть полезным.', 'Способность поддерживать без навязчивого вмешательства.', 'Тревога, заставляющая решать за другого.', 'Могу ли я побыть рядом, не предлагая готового решения?', 'В одном разговоре спроси: «Хочешь, я просто послушаю?»'],
            ['61', 'Своё желание тоже имеет значение', 'Шестёрка обращает внимание на близких, единица — на личную волю. Шестьдесят один предлагает исследовать незаметный момент, когда человек перестаёт спрашивать себя, чего хочет, потому что привык учитывать всех остальных.', 'Право на собственный выбор без отказа от любви.', 'Чувство вины при любой заботе о себе.', 'Какое моё желание давно стоит в конце списка?', 'Сделай одно небольшое дело исключительно потому, что оно важно тебе.'],
            ['62', 'Взаимность вместо подсчёта', 'Шестёрка символизирует заботу, двойка — отношения. В числе 62 можно увидеть тонкую разницу между взаимностью и бухгалтерией чувств. Считать каждый жест утомительно, но полностью игнорировать дисбаланс тоже опасно.', 'Умение просить о поддержке так же естественно, как предлагать её.', 'Тайное ожидание, что другой угадает цену наших усилий.', 'О какой помощи мне трудно попросить прямо?', 'Сформулируй одну конкретную просьбу без намёков и упрёков.'],
            ['63', 'Говорить о потребностях', 'Шестёрка заботится, тройка выражает. Число 63 напоминает: молчаливое служение иногда кажется благородным, пока не превращается в обиду. О потребностях можно говорить без обвинений; близкие не обязаны читать мысли.', 'Тёплая честность в повседневных отношениях.', 'Ожидание признания за то, что не было озвучено.', 'Какую потребность я надеюсь, что другой заметит сам?', 'Произнеси фразу «Мне было бы важно…» и закончи её конкретно.'],
            ['64', 'Забота о себе как о доме', 'Шестёрка связана с вниманием к живому, четвёрка — с основой и порядком. Шестьдесят четыре предлагает посмотреть на повседневность не как на список обязанностей, а как на среду, в которой живёт твоё внимание. Иногда забота начинается с самого простого.', 'Бережные привычки, поддерживающие силы.', 'Жёсткие бытовые стандарты, из-за которых невозможно отдохнуть.', 'Что в моём ежедневном ритме помогает мне чувствовать себя живым?', 'Сделай одно небольшое улучшение пространства без стремления к идеалу.'],
            ['65', 'Любовь не отменяет изменения', 'Шестёрка символизирует привязанность, пятёрка — движение. Шестьдесят пять напоминает: мы часто хотим, чтобы близкие оставались такими, какими привыкли их знать. Но человек меняется, и любовь требует время от времени знакомиться с ним заново.', 'Готовность видеть в близком живого человека, а не прежнюю роль.', 'Попытка удержать другого в удобном образе.', 'Что нового я давно не спрашивал у близкого человека?', 'Спроси, что изменилось в его желаниях за последний год.'],
            ['67', 'Тишина, которую не нужно заполнять', 'Шестёрка напоминает о близости, семёрка — о внутреннем мире. Число 67 показывает, что забота не всегда означает разговор. Иногда человеку важно просто побыть одному, и уважение к этому не является холодностью.', 'Доверие, позволяющее другому иметь внутреннее пространство.', 'Восприятие чужой потребности в одиночестве как личного отказа.', 'Когда я путаю заботу с постоянным присутствием?', 'Дай близкому время наедине с собой без требований объясниться.'],
            ['68', 'Не превращать любовь в долг', 'Шестёрка связана с заботой, восьмёрка — с ресурсами и ответственностью. Шестьдесят восемь напоминает: деньги, труд и подарки могут выражать любовь, но не должны становиться инструментом власти. Щедрость перестаёт быть свободной, когда за неё выставляют счёт.', 'Зрелое распределение ресурсов без скрытых условий.', 'Контроль через материальную помощь или чувство долга.', 'Какую благодарность я ожидаю за свою поддержку?', 'Вспомни один жест помощи и честно назови, было ли у него условие.'],
            ['69', 'Отпустить роль спасателя', 'Шестёрка символизирует заботу, девятка — завершение. Число 69 предлагает задуматься, не пора ли завершить роль человека, который всегда должен всех удерживать. Иногда самое уважительное действие — позволить другому встретиться с последствиями собственного выбора.', 'Сострадание без присвоения чужой ответственности.', 'Страх стать ненужным, если перестать спасать.', 'Что я продолжаю делать за другого, хотя он способен справиться сам?', 'Выбери одну чужую задачу, которую можно бережно вернуть её владельцу.']
  ];
  $count = 0;
  foreach ($entries as $entry) {
   [$number,$title,$symbolism,$light,$shadow,$question,$practice] = $entry;
   $record = NumberMeaning::query()->where('number',$number)->first();
